// src/jobs/jobs.js
export const store = {
  applied: {},      // id => result
  status: {},       // id => 'pending' | 'success' | 'failed'
};

export async function applyJob(id, work) {
  // If already succeeded, return stored result
  if (store.applied[id] !== undefined) {
    return store.applied[id];
  }

  // If previously failed, we allow retry (resume)
  if (store.status[id] === 'failed') {
    // clear failure state to allow retry
    delete store.status[id];
  }

  // Mark as pending before execution
  store.status[id] = 'pending';
  try {
    const result = await work();
    store.applied[id] = result;
    store.status[id] = 'success';
    return result;
  } catch (err) {
    // Record failure but keep status as failed so caller can handle
    store.status[id] = 'failed';
    // Optionally store error details
    store.applied[id] = err;
    throw err;
  }
}
```

