import test from 'node:test';
import assert from 'node:assert/strict';
import { applyJob, store } from './jobs.js';

test('applies once', async () => {
  // reset store
  Object.keys(store.applied).forEach(k => delete store.applied[k]);
  Object.keys(store.status).forEach(k => delete store.status[k]);

  const result = await applyJob('j1', () => Promise.resolve(1));
  assert.strictEqual(result, 1);
});

test('duplicate apply returns same result', async () => {
  const result = await applyJob('j2', () => Promise.resolve(42));
  assert.strictEqual(result, 42);
  const again = await applyJob('j2', () => Promise.resolve(42));
  assert.strictEqual(again, 42);
});

test('failure then resume', async () => {
  // First apply fails
  await assert.rejects(
    applyJob('j3', () => Promise.reject(new Error('boom'))),
    { message: /boom/ }
  );

  // Verify failure recorded (status.failed)
  assert.strictEqual(store.status['j3'], 'failed');

  // Subsequent call should retry and succeed
  const success = await applyJob('j3', () => Promise.resolve('ok'));
  assert.strictEqual(success, 'ok');
  // After success, applied should have result
  assert.strictEqual(store.applied['j3'], 'ok');
});
